-- 0043: Correct demonstrably-wrong robot-type classifications and remove a false/jargon
-- BOM line from public project pages.
--
-- Two public-facing data-quality faults, both generated by the import pipeline:
--
-- 1. robot_category is wrong for several prominent projects, and the stored summary/description
--    repeat the wrong category verbatim. Worst offenders are among the catalogue's most-starred,
--    most-visible pages:
--      * apollo (26,903★, ApolloAuto/apollo)  — an open autonomous-driving platform, filed as
--        `humanoid`; also project_kind `unknown`, so its page says BOM generation is "blocked".
--      * robotgo (10,766★, go-vgo/robotgo)    — a Go GUI-automation library, filed as `quadruped`.
--      * openmower (6,755★, ClemensElflein/OpenMower) — a DIY RTK-GPS lawn-mowing robot, filed as
--        `other` / kind `unknown`.
--      * opencat-quadruped-robot (5,557★, PetoiCamp/OpenCat-Quadruped-Robot) — a quadruped robot
--        framework, filed as `humanoid`.
--      * arduino-quadruped-robot — category `hexapod` for a quadruped.
--      * technician13-quadruped-robot-component — category `humanoid` for a quadruped component.
--      * freenove-big-hexapod-robot-kit-for-raspberry-pi — a hexapod kit filed as `other`.
--
-- 2. 289 project pages carry the sentence "Hardware BOM generation is blocked until the project is
--    classified." It is internal jargon shown to visitors and, for projects that will never be
--    reclassified, effectively a false promise. Replaced with an honest line.
--
-- Every value below is taken from the project's own public repository metadata (fetched
-- 2026-11-12); nothing is inferred. Idempotent and row-guarded by slug, so a database without the
-- imported catalogue is a no-op rather than an error, and re-running changes nothing.

-- (1) Full record corrections for the four most-visible misclassified projects.
UPDATE projects SET
  project_kind = 'robotics_software',
  robot_category = 'other',
  summary = 'Apollo is Baidu''s open autonomous-driving platform for self-driving vehicles. RoboPartPicker catalogs its public repository and indexed files.',
  description = 'Apollo is an open autonomous-driving platform: its software stack covers perception, prediction, planning and control for self-driving vehicles. This page indexes the project''s public repository and the files RoboPartPicker has catalogued. Apollo is a software platform, not a robot chassis, so no hardware bill of materials applies.',
  updated_at = '2026-11-12T02:20:00.000Z'
WHERE slug = 'apollo';

UPDATE projects SET
  project_kind = 'robotics_software',
  robot_category = 'other',
  summary = 'robotgo is a cross-platform Go library for GUI automation (mouse, keyboard and screen control). RoboPartPicker catalogs its public repository and indexed files.',
  description = 'robotgo is a Go library for cross-platform GUI automation: controlling the mouse, keyboard, screen and windows from Go code. This page indexes the project''s public repository and the files RoboPartPicker has catalogued. It is a general software library, not a quadruped robot, so no hardware bill of materials applies.',
  updated_at = '2026-11-12T02:20:00.000Z'
WHERE slug = 'robotgo';

UPDATE projects SET
  project_kind = 'physical_design',
  robot_category = 'mobile',
  summary = 'OpenMower upgrades an off-the-shelf robotic lawn mower into a smart, RTK-GPS-guided mower. RoboPartPicker catalogs its repository and hardware resources.',
  description = 'OpenMower turns a cheap off-the-shelf robotic lawn mower into a smart, RTK-GPS-guided mowing robot. It is an open-source project with dedicated hardware repositories (Sabo and YardForce mower conversions plus universal hardware) alongside its firmware and software. This page indexes the project''s public repository and the files RoboPartPicker has catalogued. No priced bill of materials has been published for the build yet.',
  updated_at = '2026-11-12T02:20:00.000Z'
WHERE slug = 'openmower';

UPDATE projects SET
  robot_category = 'quadruped',
  summary = 'OpenCat is Petoi''s open-source quadruped robot framework for four-legged robots such as Bittle and Nybble. RoboPartPicker catalogs its repository and indexed files.',
  description = 'OpenCat is Petoi''s open-source framework for Boston Dynamics-style quadruped robots, used by the Bittle and Nybble kits for STEM, research and DIY builds. This page indexes the project''s public repository and the files RoboPartPicker has catalogued. The robot kits are sold by Petoi; the repository publishes the control framework rather than a priced bill of materials.',
  updated_at = '2026-11-12T02:20:00.000Z'
WHERE slug = 'opencat-quadruped-robot';

-- (2) Category-only corrections where the slug names the robot type unambiguously. The stored
--     description repeats the old category, so the same phrase is corrected in place.
UPDATE projects SET robot_category = 'quadruped', updated_at = '2026-11-12T02:20:00.000Z',
  description = REPLACE(description, 'The catalog category is hexapod.', 'The catalog category is quadruped.')
WHERE slug = 'arduino-quadruped-robot'
  AND instr(description, 'The catalog category is hexapod.') > 0;

UPDATE projects SET robot_category = 'quadruped', updated_at = '2026-11-12T02:20:00.000Z',
  description = REPLACE(description, 'the catalog category is humanoid.', 'the catalog category is quadruped.')
WHERE slug = 'technician13-quadruped-robot-component'
  AND instr(description, 'the catalog category is humanoid.') > 0;

UPDATE projects SET robot_category = 'hexapod', project_kind = 'physical_design',
  updated_at = '2026-11-12T02:20:00.000Z',
  description = REPLACE(description, 'The catalog lists the kit under the category "other."', 'The catalog lists the kit under the category "hexapod."')
WHERE slug = 'freenove-big-hexapod-robot-kit-for-raspberry-pi'
  AND instr(description, 'The catalog lists the kit under the category "other."') > 0;

-- (3) Sweep the remaining internal-jargon sentence off every public page that still carries it.
UPDATE projects SET
  description = REPLACE(description,
    'Hardware BOM generation is blocked until the project is classified.',
    'No bill of materials has been published for this project yet.'),
  updated_at = '2026-11-12T02:20:00.000Z'
WHERE instr(description, 'Hardware BOM generation is blocked until the project is classified.') > 0;
